  function clRows(){if(state.clMode==='empty'||state.year!==2026||state.month!==10)return [];return [...pRows(),{id:74001,day:20,time:'09:15',title:'工资收入',category:'工资',account:'招商银行',icon:'briefcase-business',amount:12000,type:'income',tag:'工作日'},{id:74002,day:20,time:'10:20',title:'账户互转',category:'转账',account:'微信 → 招商银行',icon:'arrow-left-right',amount:500,type:'transfer',tag:''},{id:74003,day:20,time:'11:30',title:'美元午餐',category:'餐饮',account:'美元账户',icon:'utensils',amount:12,currency:'USD',currencyCode:'USD',nativeAmount:85.2,type:'expense',tag:''},{id:74004,day:20,time:'16:00',title:'不计收支仍然显示',category:'餐饮',account:'微信',icon:'utensils',amount:30,type:'expense',excludeStats:true,tag:''}];}
