  function clFixtureRow(r){return cCalendarTransaction(r);}
  function clSelected(){if(state.clSelected==null)return '';const rows=clRows().filter(r=>r.day===state.clSelected).sort((a,b)=>b.time.localeCompare(a.time)),date=new Date(state.year,state.month-1,state.clSelected);return `<div class="cl-day-heading" data-stacked="${qPreview.width<344||qPreview.scale>1.2}"><span><b>${state.month}月${state.clSelected}日</b><small> ${['周日','周一','周二','周三','周四','周五','周六'][date.getDay()]}</small></span>${btn('cl-add',`${icon('plus')}在该日记账`,'在该日记账','bc-secondary')}</div>${surface(rows.length?rows.map(r=>r.id>=74000?clFixtureRow(r):entry(r)).join(''):'<div class="cl-empty">当天无交易</div>','cl-transactions c3-consumer-list')}`;}
  function clPage(){const index=state.year*12+state.month,lower=2000*12+1,upper=clLast.year*12+clLast.month,body=state.clMode==='loading'?'<div class="cl-loading" role="status">正在读取日历…</div>':state.clMode==='error'?`<div class="cl-empty"><p>Error: 日历读取失败</p>${btn('cl-retry','重试','重试','bc-primary')}</div>`:surface(`<div class="cl-month-heading">${btn('cl-prev',icon('chevron-left'),'上个月','',index<=lower?'disabled':'')}${btn('cl-month',`${state.year}年${state.month}月${icon('chevron-down')}`,'选择日历月份','')}${btn('cl-next',icon('chevron-right'),'下个月','',index>=upper?'disabled':'')}</div>${clGrid()}`,'cl-month-card');return `<div class="cl-shell">${subhead('日历','cl-today').replace(icon('ellipsis'),'今天').replace('更多操作','今天')}<div class="cl-scroll">${body}${state.clMode==='ready'||state.clMode==='empty'?clSelected():''}</div></div>`;}
