  const clPreviousRender=fRender;fRender=function(key){if(clScenes.some(s=>s[0]===key)){clPrepare(key);return clPage();}return clPreviousRender(key);};
  rSpecs['cl-month']={title:'选择月份',host:'calendar',kind:'sheet'};
  function clMonthBody(){const d=jDraft('month'),years=Array.from({length:clLast.year-1999},(_,i)=>2000+i),months=Array.from({length:d.year===clLast.year?clLast.month:12},(_,i)=>i+1);return `<div class="j-picker-summary">${d.year}年${d.month}月</div>${jWheelGroup(jWheel('year',years,d.year,'年','年份')+jWheel('month',months,d.month,'月','月份'))}<p class="bc-small">可浏览2000年1月至2027年10月（今天后365天）</p><div class="j-picker-actions">${btn('r-close','取消','取消选择月份','bc-secondary')}${btn('cl-confirm-month','确定','确定日历月份','bc-primary')}</div>`;}
