  const clReadWheel=jWheelRead;jWheelRead=function(w){clReadWheel(w);if(state.rModal==='cl-month'&&w.dataset.jWheel==='year'){const d=state.jWheel,max=d.year===clLast.year?clLast.month:12;d.month=Math.min(d.month,max);const wheel=phone.querySelector('[data-j-wheel="month"]');wheel.innerHTML=Array.from({length:max},(_,i)=>i+1).map(n=>btn(`j-wheel:month:${n}`,n+'月',n+'月','j-wheel-option',`role="option" aria-selected="${n===d.month}" data-value="${n}"`)).join('');wheel.scrollTop=(d.month-1)*44;}};
  root.addEventListener('click',e=>{const el=e.target.closest('[data-action]'),action=el?.dataset.action;if(!action?.startsWith('cl-'))return;e.preventDefault();e.stopImmediatePropagation();const[key,value]=action.split(':');if(key==='cl-prev'||key==='cl-next'){const d=new Date(state.year,state.month-1+(key==='cl-next'?1:-1),1);state.year=d.getFullYear();state.month=d.getMonth()+1;state.clSelected=null;}else if(key==='cl-today')Object.assign(state,{...clToday,clSelected:clToday.day});else if(key==='cl-day'){state.day=Number(value);state.clSelected=state.day;}else if(key==='cl-month'){state.jWheel={kind:'month',year:state.year,month:state.month};rOpenModal('cl-month');return;}else if(key==='cl-confirm-month'){for(const w of phone.querySelectorAll('[data-j-wheel]'))jWheelRead(w);state.year=state.jWheel.year;state.month=state.jWheel.month;state.clSelected=null;rDismiss();}else if(key==='cl-retry')state.clMode='ready';else if(key==='cl-add'||key==='cl-row'){const row=key==='cl-row'?clRows().find(r=>r.id===Number(value)):null;state.day=state.clSelected||clToday.day;state.fForm.recordDate=`${state.year}-${jPad(state.month)}-${jPad(state.day)}`;state.fForm.recordTime=row?.time||'12:00';state.recordTime=state.fForm.recordTime;state.note=row?.title||'';state.expression=String(row?.amount||0);state.recordType=row?.type||'expense';navigate('editor');return;}render();},true);
